package main

import (
	"fmt"
	"go/ast"
	"go/types"
	"golang.org/x/tools/go/packages"
)

func main() {
	cfg := &packages.Config{
		Mode: packages.LoadAllSyntax,
		Dir: "/tmp/builtintest",
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		panic(err)
	}
	for _, pkg := range pkgs {
		fmt.Printf("pkg %s\n", pkg.PkgPath)
		for _, f := range pkg.Syntax {
			ast.Inspect(f, func(n ast.Node) bool {
				if call, ok := n.(*ast.CallExpr); ok {
					tv, ok := pkg.TypesInfo.Types[call]
					if ok {
						fmt.Printf("call %s type %s (%T) isValue %v\n", astToString(call.Fun), tv.Type.String(), tv.Type, tv.IsValue())
						// check results
						if sig, ok := tv.Type.(*types.Signature); ok {
							fmt.Printf("  sig results: %s\n", sig.Results())
						} else {
							// for calls, Types[call] is result type? Actually for calls, need to look at type?
							fmt.Printf("  not sig, type %T\n", tv.Type)
						}
						// try to get signature via Fun?
						switch fun := call.Fun.(type) {
						case *ast.Ident:
							obj := pkg.TypesInfo.Uses[fun]
							fmt.Printf("  ident %s obj %v (%T)\n", fun.Name, obj, obj)
							if obj != nil {
								fmt.Printf("    obj type %s\n", obj.Type().String())
							}
						}
					} else {
						fmt.Printf("call %s no Types entry\n", astToString(call.Fun))
					}
				}
				return true
			})
		}
	}
}

func astToString(e ast.Expr) string {
	switch x := e.(type) {
	case *ast.Ident:
		return x.Name
	case *ast.SelectorExpr:
		return astToString(x.X) + "." + x.Sel.Name
	default:
		return fmt.Sprintf("%T", e)
	}
}
EOF
