package main

import (
	"bufio"
	"flag"
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
	"unicode"

	"golang.org/x/tools/go/packages"
)

type ignoreFlagValue struct {
	m map[string]*regexp.Regexp
}

func (f *ignoreFlagValue) String() string {
	return ""
}

func (f *ignoreFlagValue) Set(s string) error {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	for _, part := range parts {
		var pkg, reStr string
		if idx := strings.Index(part, ":"); idx >= 0 {
			pkg = part[:idx]
			reStr = part[idx+1:]
		} else {
			pkg = ""
			reStr = part
		}
		re, err := regexp.Compile(reStr)
		if err != nil {
			return err
		}
		if f.m == nil {
			f.m = make(map[string]*regexp.Regexp)
		}
		f.m[pkg] = re
	}
	return nil
}

type tagsFlagValue struct {
	tags []string
}

func (f *tagsFlagValue) String() string {
	return strings.Join(f.tags, ",")
}

func (f *tagsFlagValue) Set(s string) error {
	if s == "" {
		return nil
	}
	fields := strings.FieldsFunc(s, func(r rune) bool {
		return r == ',' || unicode.IsSpace(r)
	})
	f.tags = append(f.tags, fields...)
	return nil
}

var (
	genRegexp = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)
)

var internalExcludes = []string{
	"fmt.Print",
	"fmt.Println",
	"fmt.Printf",
	"fmt.Fprint(os.Stderr)",
	"fmt.Fprintf(os.Stderr)",
	"fmt.Fprintln(os.Stderr)",
	"(*bytes.Buffer).Write",
	"(*bytes.Buffer).WriteString",
	"(*bytes.Buffer).WriteByte",
	"(*bytes.Buffer).WriteRune",
	"(*strings.Builder).Write",
	"(*strings.Builder).WriteString",
	"(*strings.Builder).WriteByte",
	"(*strings.Builder).WriteRune",
	"(hash.Hash).Write",
	"(hash.Hash32).Write",
	"(hash.Hash64).Write",
}

type excludeEntry struct {
	funcPart   string
	qualifier  string
	hasQual    bool
	isMethod   bool
	recv       string
	methodName string
	pkgPath    string
	funcName   string
}

func parseExcludeEntry(s string) excludeEntry {
	var e excludeEntry
	funcPart := s
	qual := ""
	hasQ := false
	if strings.HasSuffix(s, ")") {
		if idx := strings.LastIndex(s, "("); idx >= 0 {
			funcPart = s[:idx]
			qual = s[idx+1 : len(s)-1]
			hasQ = true
		}
	}
	e.funcPart = funcPart
	e.qualifier = qual
	e.hasQual = hasQ
	if strings.HasPrefix(funcPart, "(") {
		e.isMethod = true
		// find ")."
		if idx := strings.Index(funcPart, ")."); idx >= 0 {
			recv := funcPart[1:idx]
			method := funcPart[idx+2:]
			e.recv = recv
			e.methodName = method
		} else {
			// invalid, leave empty (will never match)
			e.recv = ""
			e.methodName = ""
		}
	} else {
		e.isMethod = false
		if idx := strings.LastIndex(funcPart, "."); idx >= 0 {
			e.pkgPath = funcPart[:idx]
			e.funcName = funcPart[idx+1:]
		} else {
			e.pkgPath = ""
			e.funcName = ""
		}
	}
	return e
}

type checker struct {
	blank           bool
	asserts         bool
	verbose         bool
	abspath         bool
	ignoreGenerated bool
	ignoreMap       map[string]*regexp.Regexp
	ignorePkgSet    map[string]bool
	excludes        []excludeEntry
	errIface        *types.Interface
}

func (c *checker) isIgnored(pkgPath, name string) bool {
	if c.ignorePkgSet[pkgPath] {
		return true
	}
	if re, ok := c.ignoreMap[pkgPath]; ok {
		if re.MatchString(name) {
			return true
		}
	}
	if pkgPath != "" {
		if re, ok := c.ignoreMap[""]; ok {
			if re.MatchString(name) {
				return true
			}
		}
	}
	return false
}

func isErrorType(t types.Type, errIface *types.Interface) bool {
	switch t.(type) {
	case *types.Named, *types.Pointer:
		return types.Implements(t, errIface)
	default:
		return false
	}
}

func main() {
	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	var (
		abspath         = fs.Bool("abspath", false, "print absolute paths to files")
		asserts         = fs.Bool("asserts", false, "if true, check for ignored type assertion results")
		blank           = fs.Bool("blank", false, "if true, check for errors assigned to blank identifier")
		exclude         = fs.String("exclude", "", "Path to a file containing a list of functions to exclude from checking")
		excludeOnly     = fs.Bool("excludeonly", false, "Use only excludes from -exclude file")
		ignoreGenerated = fs.Bool("ignoregenerated", false, "if true, checking of files with generated code is disabled")
		ignorePkg       = fs.String("ignorepkg", "", "comma-separated list of package paths to ignore")
		ignoreTests     = fs.Bool("ignoretests", false, "if true, checking of _test.go files is disabled")
		modFlag         = fs.String("mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")
		verbose         = fs.Bool("verbose", false, "produce more verbose logging")
	)
	ignoreVal := &ignoreFlagValue{m: make(map[string]*regexp.Regexp)}
	fs.Var(ignoreVal, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
	tagsVal := &tagsFlagValue{}
	fs.Var(tagsVal, "tags", "comma or space-separated list of build tags to include")

	if err := fs.Parse(os.Args[1:]); err != nil {
		os.Exit(2)
	}

	// build ignorePkg set
	ignorePkgSet := make(map[string]bool)
	if *ignorePkg != "" {
		parts := strings.Split(*ignorePkg, ",")
		for _, p := range parts {
			if p == "" {
				continue
			}
			ignorePkgSet[p] = true
		}
	}

	// load excludes
	var excludes []excludeEntry
	if !*excludeOnly {
		for _, s := range internalExcludes {
			excludes = append(excludes, parseExcludeEntry(s))
		}
	}
	if *exclude != "" {
		f, err := os.Open(*exclude)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Could not read exclude file: %v\n", err)
			os.Exit(2)
		}
		scanner := bufio.NewScanner(f)
		for scanner.Scan() {
			line := scanner.Text()
			if line == "" {
				continue
			}
			if strings.HasPrefix(line, "//") {
				continue
			}
			excludes = append(excludes, parseExcludeEntry(line))
		}
		f.Close()
		// ignore scanner errors? probably not needed
	}

	patterns := fs.Args()
	if len(patterns) == 0 {
		patterns = []string{"."}
	}

	var buildFlags []string
	if len(tagsVal.tags) > 0 {
		buildFlags = append(buildFlags, "-tags="+strings.Join(tagsVal.tags, ","))
	}
	if *modFlag != "" {
		buildFlags = append(buildFlags, "-mod="+*modFlag)
	}

	cfg := &packages.Config{
		Mode:       packages.LoadAllSyntax,
		Tests:      !*ignoreTests,
		BuildFlags: buildFlags,
	}
	pkgs, err := packages.Load(cfg, patterns...)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		os.Exit(2)
	}
	// check for errors in packages
	for _, pkg := range pkgs {
		if len(pkg.Errors) > 0 {
			// format as in original: errors while loading package <pkg>: [<errors>]
			// pkg name: use pkg.PkgPath? Or pkg.ID? For "foo" (nonexistent), PkgPath is "foo"? ID is "foo"? For "./..." failing, PkgPath? Let's use first pattern? Actually need to determine.
			// For "foo", pkg.ID is "foo", PkgPath is "foo"? For "./emptydir" failing, ID is "./emptydir"? PkgPath?
			// Let's use pkg.ID? Or pkg.PkgPath? For "foo", both "foo". For "./emptydir", ID is "example.com/.../emptydir"? Or "./emptydir"? Hmm.
			// Original error for "./emptydir" in /tmp/emptytest: "errors while loading package ./emptydir: ..."
			// So it uses pattern "./emptydir", not full path. That suggests it uses pkg.ID? For "./emptydir" with no package, ID might be "./emptydir"? Let's check by printing in our code? For now, use pkg.ID if PkgPath empty? Or use pkg.PkgPath if non-empty else ID?
			// Actually for failing packages, PkgPath may be empty? Let's use ID.
			// For "example.com/twofail/a" failing, original says "errors while loading package example.com/twofail/a: ..." (full path, not "./..."). So for "./..." pattern expanding to multiple, it uses PkgPath (full), not pattern. Good.
			// So logic: if len(patterns)==1 and package corresponds to pattern? Hmm.
			// Simpler: use pkg.PkgPath if non-empty, else pkg.ID? For "foo" (nonexistent), PkgPath is "foo"? (since no package, PkgPath might be "foo"?). For "./emptydir" failing (no Go files), PkgPath might be "example.com/emptytest/emptydir"? But original says "./emptydir", not full path. So for that case, PkgPath would be full, but original uses "./emptydir" (pattern). Hmm.
			// Let's inspect packages.Load behavior for these cases via our inspect program later. For now, try to match by using pkg.ID?
			// For "./emptydir" failing, ID is likely "./emptydir"? Or "example.com/emptytest/emptydir"? Need to check.
			// We'll implement as: pkgName := pkg.PkgPath; if pkgName == "" { pkgName = pkg.ID }
			// And for "./emptydir" case, if PkgPath is full but original expects "./emptydir", we'll be wrong. Need to investigate.
			pkgName := pkg.PkgPath
			if pkgName == "" {
				pkgName = pkg.ID
			}
			fmt.Fprintf(os.Stderr, "error: failed to check packages: errors while loading package %s: [%v]\n", pkgName, joinErrors(pkg.Errors))
			os.Exit(2)
		}
	}

	errType := types.Universe.Lookup("error").Type()
	errIface := errType.Underlying().(*types.Interface)

	c := &checker{
		blank:           *blank,
		asserts:         *asserts,
		verbose:         *verbose,
		abspath:         *abspath,
		ignoreGenerated: *ignoreGenerated,
		ignoreMap:       ignoreVal.m,
		ignorePkgSet:    ignorePkgSet,
		excludes:        excludes,
		errIface:        errIface,
	}

	type report struct {
		filename string // absolute for sorting
		line     int
		col      int
		hasCol   bool
		msg      string // trimmed line or ??
		verbose  string // prefix for verbose, or ""?
		display  string // final display filename (relative or absolute)?
	}

	var reports []report
	seen := make(map[string]bool) // dedup by filename:line:col:msg:verbose?

	cwd, _ := os.Getwd()

	for _, pkg := range pkgs {
		if *verbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", pkg.PkgPath)
		}
		if pkg.Types == nil || pkg.Fset == nil {
			continue
		}
		for _, file := range pkg.Syntax {
			// get filename for this file
			posn := pkg.Fset.Position(file.Pos())
			actualFilename := posn.Filename // absolute? from go/packages, should be absolute
