						filenameAbs := pos.Filename
						// if remapped? pos.Filename may differ from actualFilename? For //line, pos.Filename is remapped (could be relative or absolute). Need to handle.
						// For sorting, need absolute: if pos.Filename is relative (like "foo.go" or "a/b/c.go"), join with cwd? If absolute, use as is.
						absForSort := filenameAbs
						if !filepath.IsAbs(absForSort) {
							absForSort = filepath.Join(cwd, absForSort)
						}
						// check if remapped (pos.Filename != actualFilename? But actualFilename is absolute, pos.Filename could be relative or absolute remapped. How to detect remapped? Compare base? Actually for normal (non-remapped), pos.Filename should equal actualFilename (both absolute, same file). For remapped, pos.Filename is different (remapped name, could be relative or absolute, different from actual). So if pos.Filename != actualFilename, it's remapped.
						isRemapped := pos.Filename != actualFilename
						var col int
						var hasCol bool
						var msg string
						if isRemapped {
							hasCol = false
							msg = readLine(pos.Filename, pos.Line, cwd)
						} else {
							hasCol = true
							col = pos.Column
							msg = readLine(actualFilename, pos.Line, cwd)
						}
						// verbose prefix for asserts? none (as observed, no prefix)
						key := fmt.Sprintf("%s:%d:%d:%s", absForSort, pos.Line, col, msg)
						if seen[key] {
							return true
						}
						seen[key] = true
						reports = append(reports, report{filename: absForSort, line: pos.Line, col: col, hasCol: hasCol, msg: msg, verbose: ""})
					}
				}
				return true
			})
		}
	}

	// sort reports by filename (absolute), line, col
	sort.Slice(reports, func(i, j int) bool {
		if reports[i].filename != reports[j].filename {
			return reports[i].filename < reports[j].filename
		}
		if reports[i].line != reports[j].line {
			return reports[i].line < reports[j].line
		}
		return reports[i].col < reports[j].col
	})

	// print
	for _, r := range reports {
		display := r.filename
		if !*abspath {
			if rel, err := filepath.Rel(cwd, display); err == nil {
				display = rel
			}
		}
		// for verbose, need prefix? For errors (calls), prefix is func signature if selector? For blank assignments? No prefix? Actually earlier we saw blank assignments have no prefix even in verbose? Let's check: for `_ = foo()` (ident), no prefix. For `_, _ = bar()` (ident), no prefix. For `_, _ = t.M()` (method, selector)? Does blank assignment with method have prefix in verbose? We haven't tested! Need to test: `_, _ = t.M()` where t.M is method returning (int, error), with -blank -verbose, does output include prefix `(T).M`?
		// Similarly for `var _ = foo()`? No prefix. For `var _, _ = pkg.Func()`? Does it have prefix?
		// We need to test blank verbose for selector calls.
		if *verbose && r.verbose != "" {
			if r.hasCol {
				fmt.Printf("%s:%d:%d:\t%s\t%s\n", display, r.line, r.col, r.verbose, r.msg)
			} else {
				fmt.Printf("%s:%d:\t%s\t%s\n", display, r.line, r.verbose, r.msg)
			}
		} else {
			if r.hasCol {
				fmt.Printf("%s:%d:%d:\t%s\n", display, r.line, r.col, r.msg)
			} else {
				fmt.Printf("%s:%d:\t%s\n", display, r.line, r.msg)
			}
		}
	}

	if len(reports) > 0 {
		os.Exit(1)
	}
}

func joinErrors(errs []packages.Error) string {
	var parts []string
	for _, e := range errs {
		parts = append(parts, e.Error())
	}
	return strings.Join(parts, " ")
}

func isGenerated(file *ast.File) bool {
	for _, cg := range file.Comments {
		for _, c := range cg.List {
			if genRegexp.MatchString(c.Text) {
				return true
			}
		}
	}
	return false
}

func readLine(filename, line int, cwd string) string {
	// filename could be absolute or relative (for remapped). Need to resolve to actual file to read.
	// If filename is relative (like "foo.go" or "a/b/c.go" from //line), try cwd+filename? If exists, read; else return "??"
	// If absolute, read directly.
	var path string
	if filepath.IsAbs(filename) {
		path = filename
	} else {
		path = filepath.Join(cwd, filename)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return "??"
	}
	// split lines? Handle \n, \r\n? Use strings.Split with \n, then trim \r?
	lines := strings.Split(string(data), "\n")
	if line < 1 || line > len(lines) {
		return "??"
	}
	// lines[line-1] may end with \r (for CRLF)? TrimSpace will handle.
	s := strings.TrimSpace(lines[line-1])
	// what if line is empty after trim? Return ""? Or "??"? For normal files, line should be non-empty (contains call). For remapped with existing file but empty line? Unlikely. Return trimmed (could be "")? Original for remapped with existing file returned trimmed line (non-empty). For empty, would return ""? Let's return trimmed as is (could be "").
	return s
}

func (c *checker) checkCall(pkg *packages.Package, call *ast.CallExpr, actualFilename string, reports *[]report, seen map[string]bool, cwd string) {
	// determine if call returns error
	isErr, pkgPath, funcName := c.callReturnsError(pkg, call)
	if !isErr {
		return
	}
	// check ignore
	if c.isIgnored(pkgPath, funcName) {
		return
	}
	// check exclude (only for selector calls)
	if isSelectorCall(call) {
		if c.isExcluded(pkg, call) {
			return
		}
	}
	// report at Lparen
	pos := pkg.Fset.Position(call.Lparen)
	// handle remapped? For calls, Lparen position could be remapped via //line? Yes, if call is in remapped section? Example: linetest.go with //line, foo() call's Lparen position is remapped? Earlier we saw remapped reports with no col and ??, for foo() calls in remapped? Yes, linetest.go's foo() calls were reported as remapped (no col, ??). So need to handle remapped for calls as well (same as asserts).
	filenameAbs := pos.Filename
	absForSort := filenameAbs
	if !filepath.IsAbs(absForSort) {
		absForSort = filepath.Join(cwd, absForSort)
	}
	isRemapped := pos.Filename != actualFilename
	var col int
	var hasCol bool
	var msg string
	if isRemapped {
		hasCol = false
		msg = readLine(pos.Filename, pos.Line, cwd)
	} else {
		hasCol = true
		col = pos.Column
		msg = readLine(actualFilename, pos.Line, cwd)
	}
	var verbosePrefix string
	if c.verbose {
		verbosePrefix = c.getVerbosePrefix(pkg, call)
	}
	key := fmt.Sprintf("%s:%d:%d:%s:%s", absForSort, pos.Line, col, msg, verbosePrefix)
	if seen[key] {
		return
	}
	seen[key] = true
	*reports = append(*reports, report{filename: absForSort, line: pos.Line, col: col, hasCol: hasCol, msg: msg, verbose: verbosePrefix})
}

func isSelectorCall(call *ast.CallExpr) bool {
	_, ok := call.Fun.(*ast.SelectorExpr)
	return ok
}

func (c *checker) callReturnsError(pkg *packages.Package, call *ast.CallExpr) (bool, string, string) {
	// handle builtin recover special?
	if ident, ok := call.Fun.(*ast.Ident); ok {
