	// For now, assume explicit generic never ignored (skip ignore check). We'll handle in caller: if call.Fun is IndexExpr/IndexListExpr, skip ignore check (always report if error). Good. So here, return pkg/name but caller will skip? Or return pkg/name empty? Let's return actual pkg/name for error detection, but caller will skip ignore for IndexExpr.
	// To get pkg/name for ignore (for Ident and Selector, not Index):
	var pkgPath, funcName string
	var isIndex bool
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		if obj, ok := pkg.TypesInfo.Uses[fun]; ok {
			if fn, ok := obj.(*types.Func); ok {
				if fn.Pkg() != nil {
					pkgPath = fn.Pkg().Path()
				} else {
