					// if c.verbose { verbosePrefix = c.getVerbosePrefix(pkg, r) } // would give prefix for selector calls even in blank assignments? Need to verify.
					key := fmt.Sprintf("%s:%d:%d:%s:%s", absForSort, pos.Line, col, msg, verbosePrefix)
					if seen[key] {
						continue
					}
					seen[key] = true
					*reports = append(*reports, report{filename: absForSort, line: pos.Line, col: col, hasCol: hasCol, msg: msg, verbose: verbosePrefix})
				}
			} else if len(lhs) == 1 && results.Len() == 1 {
				// already covered by len==len case (1==1). Good.
			} else {
				// mismatched? e.g., `_, _ = foo()` where foo returns 1? Invalid Go (assignment mismatch), package wouldn't load (error). So ignore.
				return
			}
		case *ast.TypeAssertExpr:
			// two-value assert? Check if Types is Tuple
			if !c.asserts || !c.blank {
				return
			}
			if r.Type == nil {
				return // type switch, not assert
			}
			tv, ok := pkg.TypesInfo.Types[r]
			if !ok || tv.Type == nil {
				return
			}
			if _, isTuple := tv.Type.(*types.Tuple); !isTuple {
				return // single-value, handled elsewhere, not here
			}
			// two-value: len(lhs) should be 2 (v, ok) with 1 RHS? Or could be `v, ok = x.(T)`? Yes.
			if len(lhs) != 2 {
				return
			}
			// check second LHS (ok) is blank?
			ident, ok := lhs[1].(*ast.Ident)
			if !ok || ident.Name != "_" {
				return
			}
			// report at blank
			pos := pkg.Fset.Position(ident.Pos())
			absForSort := pos.Filename
			if !filepath.IsAbs(absForSort) {
				absForSort = filepath.Join(cwd, absForSort)
			}
			isRemapped := pos.Filename != actualFilename
			var col int
			var hasCol bool
			var msg string
			if isRemapped {
				hasCol = false
				msg = readLine(pos.Filename, pos.Line, cwd)
			} else {
				hasCol = true
				col = pos.Column
				msg = readLine(actualFilename, pos.Line, cwd)
			}
			key := fmt.Sprintf("%s:%d:%d:%s", absForSort, pos.Line, col, msg)
			if seen[key] {
				return
			}
			seen[key] = true
			*reports = append(*reports, report{filename: absForSort, line: pos.Line, col: col, hasCol: hasCol, msg: msg, verbose: ""})
		default:
			// single RHS not call/assert? e.g., `_, _ = a, b`? No, len(rhs)==1, so single value. If it's not call/assert, no error. Good.
			return
		}
	} else {
		// multiple RHS: len(lhs) should == len(rhs), each RHS single-valued
		if len(lhs) != len(rhs) {
			return
		}
		for i, lh := range lhs {
			ident, ok := lh.(*ast.Ident)
			if !ok || ident.Name != "_" {
				continue
			}
			if !c.blank {
				continue
			}
			rh := rhs[i]
			// rh could be CallExpr with single result? Or TypeAssert? Or other?
			// For CallExpr: check if its single result is error? Actually for multiple RHS, each call must be single-valued (since total counts match). But what if call returns multiple? Then package wouldn't load (mismatch). So assume single.
			// For TypeAssert? Could be `_, _ = x.(T), y.(U)`? Each assert single-value? Then two-value? No, each assert in multi-RHS context must be single-valued (since each LHS single). Two-value asserts require 2 LHS for 1 RHS, not 1 LHS for 1 RHS. So in multi-RHS, asserts are single-valued, not two-value. And single-value asserts are flagged separately (at X), not at blank. So for blank checking in multi-RHS, if RHS is TypeAssert (single-value), should we flag blank? No, because single-value asserts are flagged at X (if asserts), not at blank. And blank for value (first) is never flagged. Good. So for multi-RHS, only handle CallExpr, not TypeAssert.
			call, ok := rh.(*ast.CallExpr)
			if !ok {
				continue
			}
			var sig *types.Signature
			if tv, ok := pkg.TypesInfo.Types[call.Fun]; ok {
				if s, ok := tv.Type.(*types.Signature); ok {
					sig = s
				}
			}
			if sig == nil || sig.Results() == nil || sig.Results().Len() != 1 {
				continue
			}
			resType := sig.Results().At(0).Type()
			isErr := isErrorType(resType, c.errIface)
			if !isErr {
				if funIdent, ok := call.Fun.(*ast.Ident); ok {
					if obj, ok := pkg.TypesInfo.Uses[funIdent]; ok {
						if b, ok := obj.(*types.Builtin); ok && b.Name() == "recover" {
							isErr = true
						}
					}
				}
			}
			if !isErr {
				continue
			}
			_, pkgPath, funcName := c.callReturnsError(pkg, call)
			if _, isIndex := call.Fun.(*ast.IndexExpr); isIndex {
			} else if _, isIndexList := call.Fun.(*ast.IndexListExpr); isIndexList {
			} else {
				if c.isIgnored(pkgPath, funcName) {
					continue
				}
				if isSelectorCall(call) {
					if c.isExcluded(pkg, call) {
						continue
					}
				}
			}
			pos := pkg.Fset.Position(ident.Pos())
			absForSort := pos.Filename
			if !filepath.IsAbs(absForSort) {
				absForSort = filepath.Join(cwd, absForSort)
			}
			isRemapped := pos.Filename != actualFilename
			var col int
			var hasCol bool
			var msg string
			if isRemapped {
				hasCol = false
				msg = readLine(pos.Filename, pos.Line, cwd)
			} else {
				hasCol = true
				col = pos.Column
				msg = readLine(actualFilename, pos.Line, cwd)
			}
			var verbosePrefix string
			key := fmt.Sprintf("%s:%d:%d:%s:%s", absForSort, pos.Line, col, msg, verbosePrefix)
			if seen[key] {
				continue
			}
			seen[key] = true
			*reports = append(*reports, report{filename: absForSort, line: pos.Line, col: col, hasCol: hasCol, msg: msg, verbose: verbosePrefix})
		}
	}
}
EOF
"}

