type ignoreFlagValue struct {
	m map[string]*regexp.Regexp
}

func (f *ignoreFlagValue) String() string {
	return ""
}

func (f *ignoreFlagValue) Set(s string) error {
	if s == "" {
		return nil
	}
	parts := strings.Split(s, ",")
	for _, part := range parts {
		var pkg, reStr string
		if idx := strings.Index(part, ":"); idx >= 0 {
			pkg = part[:idx]
			reStr = part[idx+1:]
		} else {
			pkg = ""
			reStr = part
		}
		re, err := regexp.Compile(reStr)
		if err != nil {
			return err
		}
		if f.m == nil {
			f.m = make(map[string]*regexp.Regexp)
		}
		f.m[pkg] = re
	}
	return nil
}

type tagsFlagValue struct {
	tags []string
}

func (f *tagsFlagValue) String() string {
	return strings.Join(f.tags, ",")
}

func (f *tagsFlagValue) Set(s string) error {
	if s == "" {
		return nil
	}
	fields := strings.FieldsFunc(s, func(r rune) bool {
		return r == ',' || unicode.IsSpace(r)
	})
	f.tags = append(f.tags, fields...)
	return nil
}

var (
	genRegexp = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)
)

var internalExcludes = []string{
	"fmt.Print",
	"fmt.Println",
	"fmt.Printf",
	"fmt.Fprint(os.Stderr)",
	"fmt.Fprintf(os.Stderr)",
	"fmt.Fprintln(os.Stderr)",
	"(*bytes.Buffer).Write",
	"(*bytes.Buffer).WriteString",
	"(*bytes.Buffer).WriteByte",
	"(*bytes.Buffer).WriteRune",
	"(*strings.Builder).Write",
	"(*strings.Builder).WriteString",
	"(*strings.Builder).WriteByte",
	"(*strings.Builder).WriteRune",
	"(hash.Hash).Write",
	"(hash.Hash32).Write",
	"(hash.Hash64).Write",
}

type excludeEntry struct {
	funcPart   string
	qualifier  string
	hasQual    bool
	isMethod   bool
	recv       string
	methodName string
	pkgPath    string
	funcName   string
}

func parseExcludeEntry(s string) excludeEntry {
	var e excludeEntry
	funcPart := s
	qual := ""
	hasQ := false
	if strings.HasSuffix(s, ")") {
		if idx := strings.LastIndex(s, "("); idx >= 0 {
			funcPart = s[:idx]
			qual = s[idx+1 : len(s)-1]
			hasQ = true
		}
	}
	e.funcPart = funcPart
	e.qualifier = qual
	e.hasQual = hasQ
	if strings.HasPrefix(funcPart, "(") {
		e.isMethod = true
		// find ")."
		if idx := strings.Index(funcPart, ")."); idx >= 0 {
			recv := funcPart[1:idx]
			method := funcPart[idx+2:]
			e.recv = recv
			e.methodName = method
		} else {
			// invalid, leave empty (will never match)
			e.recv = ""
			e.methodName = ""
		}
	} else {
		e.isMethod = false
		if idx := strings.LastIndex(funcPart, "."); idx >= 0 {
			e.pkgPath = funcPart[:idx]
			e.funcName = funcPart[idx+1:]
		} else {
			e.pkgPath = ""
			e.funcName = ""
		}
	}
	return e
}

type checker struct {
	blank           bool
	asserts         bool
	verbose         bool
	abspath         bool
	ignoreGenerated bool
	ignoreMap       map[string]*regexp.Regexp
	ignorePkgSet    map[string]bool
	excludes        []excludeEntry
	errIface        *types.Interface
}

func (c *checker) isIgnored(pkgPath, name string) bool {
	if c.ignorePkgSet[pkgPath] {
		return true
	}
	if re, ok := c.ignoreMap[pkgPath]; ok {
		if re.MatchString(name) {
			return true
		}
	}
	if pkgPath != "" {
		if re, ok := c.ignoreMap[""]; ok {
			if re.MatchString(name) {
				return true
			}
		}
	}
	return false
}

func isErrorType(t types.Type, errIface *types.Interface) bool {
	switch t.(type) {
	case *types.Named, *types.Pointer:
		return types.Implements(t, errIface)
	default:
		return false
	}
}

func main() {
	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	var (
		abspath         = fs.Bool("abspath", false, "print absolute paths to files")
		asserts         = fs.Bool("asserts", false, "if true, check for ignored type assertion results")
		blank           = fs.Bool("blank", false, "if true, check for errors assigned to blank identifier")
