	}
}

func joinErrors(errs []packages.Error) string {
	var parts []string
	for _, e := range errs {
		parts = append(parts, e.Error())
	}
	return strings.Join(parts, " ")
}

func isGenerated(file *ast.File) bool {
	for _, cg := range file.Comments {
		for _, c := range cg.List {
			if genRegexp.MatchString(c.Text) {
				return true
			}
		}
	}
	return false
}

func readLine(filename, line int, cwd string) string {
	// filename could be absolute or relative (for remapped). Need to resolve to actual file to read.
	// If filename is relative (like "foo.go" or "a/b/c.go" from //line), try cwd+filename? If exists, read; else return "??"
	// If absolute, read directly.
	var path string
	if filepath.IsAbs(filename) {
		path = filename
	} else {
		path = filepath.Join(cwd, filename)
	}
	data, err := os.ReadFile(path)
	if err != nil {
		return "??"
	}
	// split lines? Handle \n, \r\n? Use strings.Split with \n, then trim \r?
