		return "??"
	}
	// lines[line-1] may end with \r (for CRLF)? TrimSpace will handle.
	s := strings.TrimSpace(lines[line-1])
	// what if line is empty after trim? Return ""? Or "??"? For normal files, line should be non-empty (contains call). For remapped with existing file but empty line? Unlikely. Return trimmed (could be "")? Original for remapped with existing file returned trimmed line (non-empty). For empty, would return ""? Let's return trimmed as is (could be "").
	return s
}

func (c *checker) checkCall(pkg *packages.Package, call *ast.CallExpr, actualFilename string, reports *[]report, seen map[string]bool, cwd string) {
	// determine if call returns error
	isErr, pkgPath, funcName := c.callReturnsError(pkg, call)
	if !isErr {
		return
	}
	// check ignore
	if c.isIgnored(pkgPath, funcName) {
		return
	}
	// check exclude (only for selector calls)
	if isSelectorCall(call) {
		if c.isExcluded(pkg, call) {
			return
		}
	}
	// report at Lparen
	pos := pkg.Fset.Position(call.Lparen)
	// handle remapped? For calls, Lparen position could be remapped via //line? Yes, if call is in remapped section? Example: linetest.go with //line, foo() call's Lparen position is remapped? Earlier we saw remapped reports with no col and ??, for foo() calls in remapped? Yes, linetest.go's foo() calls were reported as remapped (no col, ??). So need to handle remapped for calls as well (same as asserts).
	filenameAbs := pos.Filename
	absForSort := filenameAbs
	if !filepath.IsAbs(absForSort) {
		absForSort = filepath.Join(cwd, absForSort)
	}
	isRemapped := pos.Filename != actualFilename
	var col int
	var hasCol bool
	var msg string
	if isRemapped {
		hasCol = false
		msg = readLine(pos.Filename, pos.Line, cwd)
	} else {
		hasCol = true
		col = pos.Column
		msg = readLine(actualFilename, pos.Line, cwd)
	}
	var verbosePrefix string
	if c.verbose {
		verbosePrefix = c.getVerbosePrefix(pkg, call)
	}
	key := fmt.Sprintf("%s:%d:%d:%s:%s", absForSort, pos.Line, col, msg, verbosePrefix)
	if seen[key] {
		return
	}
	seen[key] = true
	*reports = append(*reports, report{filename: absForSort, line: pos.Line, col: col, hasCol: hasCol, msg: msg, verbose: verbosePrefix})
}

func isSelectorCall(call *ast.CallExpr) bool {
	_, ok := call.Fun.(*ast.SelectorExpr)
	return ok
}

func (c *checker) callReturnsError(pkg *packages.Package, call *ast.CallExpr) (bool, string, string) {
	// handle builtin recover special?
	if ident, ok := call.Fun.(*ast.Ident); ok {
		if obj, ok := pkg.TypesInfo.Uses[ident]; ok {
			if b, ok := obj.(*types.Builtin); ok {
				if b.Name() == "recover" {
					// treat as error, pkg "", name "recover"
					return true, "", "recover"
				}
				// other builtins: check return type? For copy (int), not error. For others with no return (void), not error.
				// For builtins, get signature from Types[Fun]? Types[Fun] is signature with IsBuiltin true.
				if tv, ok := pkg.TypesInfo.Types[call.Fun]; ok {
					if sig, ok := tv.Type.(*types.Signature); ok {
						results := sig.Results()
						for i := 0; i < results.Len(); i++ {
							if isErrorType(results.At(i).Type(), c.errIface) {
								// shouldn't happen for builtins except recover? But check anyway.
								return true, "", b.Name()
							}
						}
					}
				}
				return false, "", ""
			}
		}
	}
	// for IndexExpr (explicit generic), still need to check if returns error (for reporting), but pkg/name for ignore? For generic explicit, ignore never applies (as observed, always reported). So return pkg/name as ""? Or return actual pkg/name but caller will skip ignore check for IndexExpr? Simpler: return isErr=true, but pkg/name empty so ignore check will only check all-packages regex? But observed explicit generic NOT ignored even by all-packages regex? Let's test: does `-ignore 'Foo'` (all packages, regex Foo) exclude `sub.Foo[int]`? Earlier we tested `-ignore '.../sub:Foo'` (specific) didn't exclude explicit generic. What about all-packages `-ignore 'Foo'`? Let's test quickly (need to test).
	// For now, assume explicit generic never ignored (skip ignore check). We'll handle in caller: if call.Fun is IndexExpr/IndexListExpr, skip ignore check (always report if error). Good. So here, return pkg/name but caller will skip? Or return pkg/name empty? Let's return actual pkg/name for error detection, but caller will skip ignore for IndexExpr.
	// To get pkg/name for ignore (for Ident and Selector, not Index):
	var pkgPath, funcName string
	var isIndex bool
	switch fun := call.Fun.(type) {
	case *ast.Ident:
		if obj, ok := pkg.TypesInfo.Uses[fun]; ok {
			if fn, ok := obj.(*types.Func); ok {
				if fn.Pkg() != nil {
					pkgPath = fn.Pkg().Path()
				} else {
					pkgPath = ""
				}
				funcName = fn.Name()
			} else if b, ok := obj.(*types.Builtin); ok {
				pkgPath = ""
				funcName = b.Name()
			}
		}
	case *ast.SelectorExpr:
		if sel, ok := pkg.TypesInfo.Selections[fun]; ok {
			// method
			obj := sel.Obj()
			if obj.Pkg() != nil {
				pkgPath = obj.Pkg().Path()
			} else {
				pkgPath = ""
			}
			funcName = obj.Name()
		} else {
			// package func? Uses[Sel]
			if obj, ok := pkg.TypesInfo.Uses[fun.Sel]; ok {
				if fn, ok := obj.(*types.Func); ok {
					if fn.Pkg() != nil {
						pkgPath = fn.Pkg().Path()
					}
					funcName = fn.Name()
				}
			}
		}
	case *ast.IndexExpr:
		isIndex = true
		// try to get underlying? For error detection, need signature. For ignore, skip (return empty to indicate skip?).
		// For now, set pkgPath="__index__" to indicate skip? Or handle in caller by checking call.Fun type.
	case *ast.IndexListExpr:
		isIndex = true
	}
	_ = isIndex
	// determine if returns error via signature
	// get signature from Types[Fun]? For Ident/Selector, Types[Fun] is signature. For IndexExpr, Types[Fun]? For `sub.Foo[int]`, Types[IndexExpr]? Actually call.Fun is IndexExpr, Types[IndexExpr] is instantiated signature? Let's check.
	var sig *types.Signature
	if tv, ok := pkg.TypesInfo.Types[call.Fun]; ok {
		if s, ok := tv.Type.(*types.Signature); ok {
			sig = s
		}
	}
	if sig == nil {
		// fallback: try to get from object? For Ident/Selector, get from Uses/Selections?
		// For builtins already handled. For others, if no sig, assume no error?
		return false, pkgPath, funcName
	}
	results := sig.Results()
	if results == nil {
		return false, pkgPath, funcName
	}
	for i := 0; i < results.Len(); i++ {
		if isErrorType(results.At(i).Type(), c.errIface) {
			return true, pkgPath, funcName
		}
	}
	return false, pkgPath, funcName
}

func (c *checker) getVerbosePrefix(pkg *packages.Package, call *ast.CallExpr) string {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return ""
	}
	if selObj, ok := pkg.TypesInfo.Selections[sel]; ok {
		// method
		obj := selObj.Obj()
		sig, ok := obj.Type().(*types.Signature)
		if !ok || sig.Recv() == nil {
			return ""
		}
		recvType := sig.Recv().Type()
		recvStr := types.TypeString(recvType, nil)
		return "(" + recvStr + ")." + obj.Name()
	} else {
		// package func?
		if obj, ok := pkg.TypesInfo.Uses[sel.Sel]; ok {
			if fn, ok := obj.(*types.Func); ok && fn.Pkg() != nil {
				return fn.Pkg().Path() + "." + fn.Name()
			}
		}
		return ""
	}
}

func (c *checker) isExcluded(pkg *packages.Package, call *ast.CallExpr) bool {
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	var isMethod bool
	var pkgPath, funcName string
	var declRecvStr string
	var actualRecvType types.Type
	var methodName string
	if selObj, ok := pkg.TypesInfo.Selections[sel]; ok {
		isMethod = true
		obj := selObj.Obj()
		methodName = obj.Name()
		sig, ok := obj.Type().(*types.Signature)
		if !ok || sig.Recv() == nil {
			return false
		}
		declRecvStr = types.TypeString(sig.Recv().Type(), nil)
		// actual recv type from X
		if tv, ok := pkg.TypesInfo.Types[sel.X]; ok {
			actualRecvType = tv.Type
		} else {
			actualRecvType = selObj.Recv()
		}
	} else {
		// package func
		isMethod = false
		if obj, ok := pkg.TypesInfo.Uses[sel.Sel]; ok {
			if fn, ok := obj.(*types.Func); ok && fn.Pkg() != nil {
				pkgPath = fn.Pkg().Path()
				funcName = fn.Name()
			} else {
				return false
			}
		} else {
			return false
		}
	}

	for _, e := range c.excludes {
		if e.isMethod != isMethod {
			continue
		}
		if isMethod {
			if e.methodName != methodName {
				continue
			}
			// check receiver matching
			matched := false
			// declaring always candidate
			if e.recv == declRecvStr {
				matched = true
			} else {
				// if actual is interface, check actual and embedded
				if isInterfaceType(actualRecvType) {
					actualStr := types.TypeString(actualRecvType, nil)
					if e.recv == actualStr {
						matched = true
					} else if isEmbedded(actualRecvType, e.recv) {
						matched = true
					}
				}
			}
			if !matched {
				continue
			}
		} else {
			if e.pkgPath != pkgPath || e.funcName != funcName {
				continue
			}
		}
		// check qualifier
		if !e.hasQual {
			return true
		}
		// has qualifier: need first arg
		if len(call.Args) == 0 {
			continue
		}
		firstArg := call.Args[0]
		if e.qualifier == "os.Stdout" || e.qualifier == "os.Stderr" {
			// check if first arg is selector os.Stdout/Stderr via types
			if selArg, ok := firstArg.(*ast.SelectorExpr); ok {
				// get obj for Sel (package var)
				var obj types.Object
				if o, ok := pkg.TypesInfo.Uses[selArg.Sel]; ok {
					obj = o
				} else if s, ok := pkg.TypesInfo.Selections[selArg]; ok {
					obj = s.Obj()
				}
				if obj != nil && obj.Pkg() != nil && obj.Pkg().Path() == "os" && obj.Name() == e.qualifier[3:] { // "Stdout" or "Stderr" (skip "os.")
					// e.qualifier is "os.Stdout", need to compare Name "Stdout"
					// e.qualifier[3:] is "Stdout"? "os.Stdout"[3:] = "Stdout"? "os." is 3 chars, yes.
					return true
				}
			}
			continue
		} else {
			// type qualifier: check first arg type string == qualifier, and first arg is NOT direct os.Stdout/Stderr literal (special handling)
			// check if first arg is os.Stdout/Stderr literal (selector via types)? If yes, skip (do not match via type)
			if selArg, ok := firstArg.(*ast.SelectorExpr); ok {
				var obj types.Object
				if o, ok := pkg.TypesInfo.Uses[selArg.Sel]; ok {
					obj = o
				} else if s, ok := pkg.TypesInfo.Selections[selArg]; ok {
					obj = s.Obj()
				}
				if obj != nil && obj.Pkg() != nil && obj.Pkg().Path() == "os" && (obj.Name() == "Stdout" || obj.Name() == "Stderr") {
					continue
				}
			}
			// get type of first arg
			if tv, ok := pkg.TypesInfo.Types[firstArg]; ok && tv.Type != nil {
				typeStr := types.TypeString(tv.Type, nil)
				if typeStr == e.qualifier {
					return true
				}
			}
			continue
		}
	}
	return false
}

func isInterfaceType(t types.Type) bool {
	if t == nil {
		return false
	}
	// unwrap alias? For Hash32 (Named, underlying Interface), need to check underlying. For Alias to interface? Unlikely. Use types.Unalias? But original doesn't unalias for error check, but for embedding check, should we unalias? For Hash32, it's Named, not Alias, so fine. For safety, unalias?
	// Use underlying?
	if named, ok := t.(*types.Named); ok {
		if _, ok := named.Underlying().(*types.Interface); ok {
			return true
		}
		return false
	}
	if _, ok := t.Underlying().(*types.Interface); ok {
		// for *types.Interface directly? Underlying of Interface is itself. Good.
		// But need to ensure t is interface, not concrete with underlying struct? Concrete struct underlying is Struct, not Interface, so false. Good.
		// However, this would return true for any type whose underlying is Interface? That includes Named interfaces (already handled) and Interface directly. Good.
		// But what about TypeParam with interface constraint? Underlying? Might be interface? Unlikely. Return true? Possibly, but rare.
		return true
	}
	return false
}

func isEmbedded(recvType types.Type, target string) bool {
	if recvType == nil {
		return false
	}
	// get underlying interface
	var iface *types.Interface
	if named, ok := recvType.(*types.Named); ok {
		if i, ok := named.Underlying().(*types.Interface); ok {
			iface = i
		} else {
			return false
		}
	} else if i, ok := recvType.(*types.Interface); ok {
		iface = i
	} else if alias, ok := recvType.(*types.Alias); ok {
		// unalias? For Alias to interface? Check unaliased.
		un := types.Unalias(alias)
		return isEmbedded(un, target)
	} else {
		return false
	}
	// BFS/DFS over embedded
	visited := make(map[string]bool)
	var stack []types.Type
	for i := 0; i < iface.NumEmbeddeds(); i++ {
		stack = append(stack, iface.EmbeddedType(i))
	}
	for len(stack) > 0 {
		t := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		s := types.TypeString(t, nil)
		if visited[s] {
			continue
		}
		visited[s] = true
		if s == target {
			return true
		}
		// recurse into embedded of t (if t is interface)
		var innerIface *types.Interface
		if named, ok := t.(*types.Named); ok {
			if i, ok := named.Underlying().(*types.Interface); ok {
				innerIface = i
			}
		} else if i, ok := t.(*types.Interface); ok {
			innerIface = i
		} else if alias, ok := t.(*types.Alias); ok {
			un := types.Unalias(alias)
			if named, ok := un.(*types.Named); ok {
				if i, ok := named.Underlying().(*types.Interface); ok {
					innerIface = i
				}
			} else if i, ok := un.(*types.Interface); ok {
				innerIface = i
			}
		}
		if innerIface != nil {
			for i := 0; i < innerIface.NumEmbeddeds(); i++ {
				stack = append(stack, innerIface.EmbeddedType(i))
			}
		}
	}
	return false
}

